package main

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
	"text/template"
)

// tplFuncs provides template helper functions.
// q wraps strconv.Quote so values with embedded quotes or backslashes
// produce valid Go string literals in generated code.
var tplFuncs = template.FuncMap{
	"q": strconv.Quote,
}

const resourceTpl = `// Code generated by aippatchgen. DO NOT EDIT.
package patches

import (
	{{.Package}} "{{.ProtoImportPath}}"
	"github.com/btc/drill/thirdparty/aippatch"
)

// {{.GoVarName}} is the PATCH mapping for {{.Message}} -> {{.Table}}.
// Validate(Codecs) is called from InitPatches() at startup, never at package init.
var {{.GoVarName}} = &aippatch.Mapping[{{.GoType}}]{
	Table:      {{q .Table}},
	PK:         {{q .PK}},
	{{- if .SoftDelete}}
	SoftDelete: {{q .SoftDelete}},
	{{- end}}
	EmptyMask:  aippatch.{{.EmptyMask}},
	Bindings: []aippatch.Binding{
		{{- range .Bindings}}
		{Proto: {{q .Proto}}, Column: {{q .Column}}, SQLType: {{q .SQLType}}, Writable: {{.Writable}}, Codec: {{q .Codec}}},
		{{- end}}
	},
	{{- if .AutoSet}}
	AutoSet: []aippatch.AutoSetClause{
		{{- range .AutoSet}}
		{Column: {{q .Column}}, SQLLiteral: {{q .SQLLiteral}}},
		{{- end}}
	},
	{{- end}}
}
`

type resourceTplData struct {
	ResourceModel
	ProtoImportPath string
	GoVarName       string
}

func emitResource(r *ResourceModel, protoImportPath string) (string, error) {
	data := resourceTplData{
		ResourceModel:   *r,
		ProtoImportPath: protoImportPath,
		GoVarName:       goVarName(r.Message),
	}
	t, err := template.New("resource").Funcs(tplFuncs).Parse(resourceTpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		return "", err
	}
	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		return "", fmt.Errorf("aippatchgen: gofmt: %w\nsource:\n%s", err, buf.String())
	}
	return string(formatted), nil
}

// goVarName turns "drill.v1.User" -> "UserPatch".
func goVarName(fullName string) string {
	parts := strings.Split(fullName, ".")
	return parts[len(parts)-1] + "Patch"
}

const initTpl = `// Code generated by aippatchgen. DO NOT EDIT.
package patches

import (
	{{.Package}} "{{.ProtoImportPath}}"
	"github.com/btc/drill/thirdparty/aippatch"
)

// Codecs is the shared registry of enum codecs declared in aippatch.yaml.
// Validate(Codecs) selects the codecs reachable from each Mapping's Bindings.
var Codecs = map[string]aippatch.EnumCodec{
	{{- range .Codecs}}
	{{q .Name}}: {
		ProtoEnum: {{q .ProtoEnum}},
		ToText: map[int32]string{
			{{- range .Values}}
			int32({{$.Package}}.{{.GoConst}}): {{q .Text}},
			{{- end}}
		},
	},
	{{- end}}
}

// InitPatches validates every generated mapping. Call once at server startup.
// Returns the first validation error encountered; never panics.
func InitPatches() error {
	for _, fn := range []func(map[string]aippatch.EnumCodec) error{
		{{- range .Resources}}
		{{.}}.Validate,
		{{- end}}
	} {
		if err := fn(Codecs); err != nil {
			return err
		}
	}
	return nil
}
`

type initTplData struct {
	Package         string
	ProtoImportPath string
	Codecs          []CodecModel
	Resources       []string
}

func emitInit(codecs map[string]CodecModel, resources []string, pkg, protoImportPath string) (string, error) {
	keys := make([]string, 0, len(codecs))
	for k := range codecs {
		keys = append(keys, k)
	}
	// Stable order for diff.
	sort.Strings(keys)
	cs := make([]CodecModel, 0, len(keys))
	for _, k := range keys {
		cm := codecs[k]
		cm.Name = k
		// Sort enum values by number for stable diff.
		sort.Slice(cm.Values, func(i, j int) bool { return cm.Values[i].Number < cm.Values[j].Number })
		cs = append(cs, cm)
	}
	sort.Strings(resources)

	t, err := template.New("init").Funcs(tplFuncs).Parse(initTpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := t.Execute(&buf, initTplData{Package: pkg, ProtoImportPath: protoImportPath, Codecs: cs, Resources: resources}); err != nil {
		return "", err
	}
	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		return "", fmt.Errorf("aippatchgen: gofmt init: %w\nsource:\n%s", err, buf.String())
	}
	return string(formatted), nil
}
